Read text file `core/resplit.ts`.
1|// Resplit rule: split a scene only where the dominant emotion changes
2|// strongly and stays changed along the text. Pure, no network.
3|import { EMOTIONS } from "./types";
4|import type { EmotionId, Vector8 } from "./types";
5|import { countWords } from "./reader";
6|
7|export const RESPLIT_AUTO_MARGIN = 0.3;
8|export const RESPLIT_ASK_MARGIN = 0.15;
9|export const RESPLIT_MIN_PART_WORDS = 120;
10|export const RESPLIT_MIN_SCENE_WORDS = 240;
11|export const RESPLIT_CANDIDATE_WORDS = 350;
12|export const RESPLIT_LOW_TOP = 0.5;
13|export const RESPLIT_LOW_GAP = 0.15;
14|export const RESPLIT_WINDOW_MIN = 100;
15|export const RESPLIT_WINDOW_MAX = 160;
16|
17|export interface ResplitParagraph {
18|  n: number;
19|  text: string;
20|}
21|
22|export interface ResplitWindow {
23|  startN: number;
24|  endN: number;
25|  words: number;
26|  vector: Vector8;
27|}
28|
29|export type WindowSpan = Pick<ResplitWindow, "startN" | "endN" | "words">;
30|
31|export interface SplitCall {
32|  index: number;
33|  margin: number;
34|  left: EmotionId;
35|  right: EmotionId;
36|}
37|
38|export function topOf(vector: Vector8): { id: EmotionId; value: number; gap: number } {
39|  let id: EmotionId = EMOTIONS[0];
40|  let value = -Infinity;
41|  let second = -Infinity;
42|  for (const key of EMOTIONS) {
43|    const v = vector[key];
44|    if (v > value) {
45|      second = value;
46|      id = key;
47|      value = v;
48|    } else if (v > second) {
49|      second = v;
50|    }
51|  }
52|  return { id, value, gap: value - second };
53|}
54|
55|export function isResplitCandidate(words: number, final: { vector: Vector8 } | null): boolean {
56|  if (final === null || words < RESPLIT_MIN_SCENE_WORDS) return false;
57|  if (words > RESPLIT_CANDIDATE_WORDS) return true;
58|  const { value, gap } = topOf(final.vector);
59|  return value < RESPLIT_LOW_TOP || gap < RESPLIT_LOW_GAP;
60|}
61|
62|// Consecutive windows of whole paragraphs, greedily about 100 to 160
63|// words each. A single long paragraph is its own window.
64|export function buildWindows(paragraphs: ResplitParagraph[]): WindowSpan[] {
65|  const windows: WindowSpan[] = [];
66|  let startN = 0;
67|  let endN = 0;
68|  let words = 0;
69|  const flush = () => {
70|    if (words === 0 && endN === 0) return;
71|    windows.push({ startN, endN, words });
72|    startN = 0;
73|    endN = 0;
74|    words = 0;
75|  };
76|  for (const p of paragraphs) {
77|    if (words >= RESPLIT_WINDOW_MIN) flush();
78|    if (words === 0) startN = p.n;
79|    endN = p.n;
80|    words += countWords(p.text);
81|  }
82|  flush();
83|  const last = windows[windows.length - 1];
84|  const prev = windows[windows.length - 2];
85|  if (last && prev && last.words < RESPLIT_WINDOW_MIN) {
86|    prev.endN = last.endN;
87|    prev.words += last.words;
88|    windows.pop();
89|  }
90|  return windows;
91|}
92|
93|export function meanVector(windows: Pick<ResplitWindow, "words" | "vector">[]): Vector8 {
94|  const total = windows.reduce((sum, w) => sum + w.words, 0);
95|  const mean = {} as Vector8;
96|  for (const id of EMOTIONS) {
97|    mean[id] = 0;
98|    for (const w of windows) mean[id] += w.vector[id] * (total > 0 ? w.words / total : 1 / windows.length);
99|  }
100|  return mean;
101|}
102|
103|// A side holds when it reaches 120 words and the mood persists past
104|// one short window: two windows, or one window of 120 words itself.
105|function holds(windows: Pick<ResplitWindow, "words">[]): boolean {
106|  const words = windows.reduce((sum, w) => sum + w.words, 0);
107|  if (words < RESPLIT_MIN_PART_WORDS) return false;
108|  return windows.length >= 2 || (windows[0]?.words ?? 0) >= RESPLIT_MIN_PART_WORDS;
109|}
110|
111|export function bestBoundary(windows: ResplitWindow[]): SplitCall | null {
112|  let best: SplitCall | null = null;
113|  for (let index = 1; index < windows.length; index++) {
114|    const leftWindows = windows.slice(0, index);
115|    const rightWindows = windows.slice(index);
116|    if (!holds(leftWindows) || !holds(rightWindows)) continue;
117|    const left = meanVector(leftWindows);
118|    const right = meanVector(rightWindows);
119|    const a = topOf(left).id;
120|    const b = topOf(right).id;
121|    if (a === b) continue;
122|    const margin = Math.min(left[a] - left[b], right[b] - right[a]);
123|    if (best === null || margin > best.margin) best = { index, margin, left: a, right: b };
124|  }
125|  return best;
126|}
127|
128|export function decideMargin(margin: number): "auto" | "ask" | "none" {
129|  if (margin >= RESPLIT_AUTO_MARGIN) return "auto";
130|  if (margin >= RESPLIT_ASK_MARGIN) return "ask";
131|  return "none";
132|}
133|
134|// Binary segmentation: split at the strongest boundary, then recurse
135|// on each side. The asker resolves ambiguous margins; record keeps
136|// each taken boundary for provenance.
137|export async function planSplits(
138|  windows: ResplitWindow[],
139|  askSplit: (call: SplitCall) => Promise<boolean>,
140|  record?: (call: SplitCall, decidedBy: "rule" | "muse") => void,
141|): Promise<number[]> {
142|  const best = bestBoundary(windows);
143|  if (best === null || decideMargin(best.margin) === "none") return [];
144|  const kind = decideMargin(best.margin);
145|  if (kind === "ask" && !(await askSplit(best))) return [];
146|  record?.(best, kind === "ask" ? "muse" : "rule");
147|  const left = await planSplits(windows.slice(0, best.index), askSplit, record);
148|  const right = (await planSplits(windows.slice(best.index), askSplit, record)).map((i) => i + best.index);
149|  return [...left, best.index, ...right];
150|}
151|
152|// First part keeps the scene id; later parts add a letter suffix.
153|export function splitIds(baseId: string, count: number): string[] {
154|  return Array.from({ length: count }, (_, i) => (i === 0 ? baseId : `${baseId}${String.fromCharCode(97 + i)}`));
155|}

Read text file `pipeline/resplit.ts`.
1|// Step: re-split scenes where the dominant emotion changes strongly
2|// along the text. Reads book.json and analysis.json, rewrites
3|// scenes.json and analysis.json. Skips when provenance.resplit exists.
4|import { readFileSync, writeFileSync } from "node:fs";
5|import { join } from "node:path";
6|import { renormalize8 } from "../core/emotion";
7|import { countWords } from "../core/reader";
8|import {
9|  RESPLIT_ASK_MARGIN,
10|  RESPLIT_AUTO_MARGIN,
11|  bestBoundary,
12|  buildWindows,
13|  isResplitCandidate,
14|  meanVector,
15|  planSplits,
16|  splitIds,
17|} from "../core/resplit";
18|import type { ResplitWindow, SplitCall } from "../core/resplit";
19|import { validateBookCoverage } from "../core/scenes";
20|import type { AnalyzedScene, Book, EmotionId, Scene, SceneEmotion } from "../core/types";
21|import { classifyScene } from "./classify";
22|import type { ClassifyMetaUsage } from "./classify";
23|import type { StepCtx } from "./ingest";
24|import { runPool } from "./http";
25|import type { JevClient } from "./jev";
26|import type { MetaClient } from "./meta";
27|import { jevCostUsd, metaCostUsd } from "./prices";
28|
29|const DECISION_SCHEMA = {
30|  type: "object",
31|  properties: { split: { type: "boolean" }, reason: { type: "string" } },
32|  required: ["split", "reason"],
33|  additionalProperties: false,
34|};
35|
36|const TITLES_SCHEMA = {
37|  type: "object",
38|  properties: {
39|    parts: {
40|      type: "array",
41|      items: {
42|        type: "object",
43|        properties: {
44|          start_n: { type: "number" },
45|          end_n: { type: "number" },
46|          title: { type: "string" },
47|          summary: { type: "string" },
48|          characters: { type: "array", items: { type: "string" } },
49|        },
50|        required: ["start_n", "end_n", "title", "summary", "characters"],
51|        additionalProperties: false,
52|      },
53|    },
54|  },
55|  required: ["parts"],
56|  additionalProperties: false,
57|};
58|
59|export interface ResplitEntry {
60|  from: string;
61|  into: string[];
62|  at_n: number[];
63|  margin: number;
64|  left: EmotionId;
65|  right: EmotionId;
66|  decided_by: "rule" | "muse";
67|  reason?: string;
68|}
69|
70|interface Usage {
71|  jevRequests: number;
72|  jevInputTokens: number;
73|  jevOutputTokens: number;
74|  meta: ClassifyMetaUsage;
75|}
76|
77|function newUsage(model: string): Usage {
78|  return { jevRequests: 0, jevInputTokens: 0, jevOutputTokens: 0, meta: { model, requests: 0, promptTokens: 0, cachedTokens: 0, completionTokens: 0, costUsd: 0 } };
79|}
80|
81|function trackMeta(usage: Usage, result: { promptTokens: number; cachedTokens: number; completionTokens: number }): void {
82|  usage.meta.requests += 1;
83|  usage.meta.promptTokens += result.promptTokens;
84|  usage.meta.cachedTokens += result.cachedTokens;
85|  usage.meta.completionTokens += result.completionTokens;
86|}
87|
88|export async function runResplit(ctx: StepCtx, deps: { jev: JevClient; meta: MetaClient }): Promise<AnalyzedScene[]> {
89|  const book = JSON.parse(readFileSync(join(ctx.dir, "book.json"), "utf8")) as Book;
90|  const scenesFile = JSON.parse(readFileSync(join(ctx.dir, "scenes.json"), "utf8")) as {
91|    bookId: string;
92|    textVersion: string;
93|    scenes: Scene[];
94|    provenance: { meta: { model: string; requests: number; prompt_tokens: number; cached_tokens: number; completion_tokens: number; cost_usd: number } };
95|  };
96|  const analysisFile = JSON.parse(readFileSync(join(ctx.dir, "analysis.json"), "utf8")) as {
97|    bookId: string;
98|    textVersion: string;
99|    scenes: AnalyzedScene[];
100|    provenance: {
101|      date: string;
102|      jev: { model: string; requests: number; input_tokens: number; output_tokens: number; cost_usd: number };
103|      meta: { model: string; requests: number; prompt_tokens: number; cached_tokens: number; completion_tokens: number; cost_usd: number };
104|      total_cost_usd: number;
105|      resplit?: unknown;
106|    };
107|  };
108|  if (!ctx.force && analysisFile.textVersion === book.textVersion && analysisFile.provenance.resplit) {
109|    return analysisFile.scenes;
110|  }
111|  const usage = newUsage(deps.meta.model);
112|  const byN = new Map(book.paragraphs.map((p) => [p.n, p.text]));
113|  const chapterTitle = new Map(book.chapters.map((c) => [c.ch, c.title]));
114|  const wordsOf = (scene: { start_n: number; end_n: number }): number => {
115|    let words = 0;
116|    for (let n = scene.start_n; n <= scene.end_n; n++) words += countWords(byN.get(n) ?? "");
117|    return words;
118|  };
119|  const candidates = analysisFile.scenes.filter((s) => isResplitCandidate(wordsOf(s), s.final));
120|  let windowsClassified = 0;
121|
122|  const splitScenes = await runPool(candidates, 4, async (scene) => {
123|    const paragraphs = book.paragraphs.filter((p) => p.n >= scene.start_n && p.n <= scene.end_n);
124|    const spans = buildWindows(paragraphs);
125|    const windows: ResplitWindow[] = [];
126|    for (const span of spans) {
127|      const text = paragraphs.filter((p) => p.n >= span.startN && p.n <= span.endN).map((p) => p.text).join("\n");
128|      const result = await deps.jev.classify({ book: book.title, chapter: chapterTitle.get(scene.ch) ?? "", sceneTitle: scene.title, scene: text });
129|      usage.jevRequests += 1;
130|      usage.jevInputTokens += result.input_tokens;
131|      usage.jevOutputTokens += result.output_tokens;
132|      const { unknown: _dropped, ...rest } = result.vector;
133|      const vector = renormalize8(rest);
134|      if (vector === null) return null;
135|      windows.push({ ...span, vector });
136|      windowsClassified += 1;
137|    }
138|    if (windows.length < 2) return null;
139|    const taken: { call: SplitCall; by: "rule" | "muse"; reason?: string }[] = [];
140|    const cuts = await planSplits(
141|      windows,
142|      async (call) => {
143|        const boundaryN = windows[call.index]?.startN ?? 0;
144|        const before = paragraphs.filter((p) => p.n < boundaryN).slice(-2);
145|        const after = paragraphs.filter((p) => p.n >= boundaryN).slice(0, 2);
146|        const left = meanVector(windows.slice(0, call.index));
147|        const right = meanVector(windows.slice(call.index));
148|        const result = await deps.meta.completeJson({
149|          system: "You judge whether a scene needs two music tracks. Answer with JSON only.",
150|          user:
151|            `Scene "${scene.title}" may change mood at paragraph ${windows[call.index]?.startN}. ` +
152|            `Left mood ${call.left} ${JSON.stringify(left)}, right mood ${call.right} ${JSON.stringify(right)}. ` +
153|            `Split only when the dominant feeling changes strongly and stays changed, not for a mixed blend. ` +
154|            `Before: ${before.map((p) => `[${p.n}] ${p.text}`).join("\n")}\nAfter: ${after.map((p) => `[${p.n}] ${p.text}`).join("\n")}`,
155|          schemaName: "resplit_decision",
156|          schema: DECISION_SCHEMA,
157|        });
158|        trackMeta(usage, result);
159|        const data = result.data as { split?: unknown; reason?: unknown };
160|        const split = data.split === true;
161|        if (split) taken.push({ call, by: "muse", reason: String(data.reason ?? "") });
162|        return split;
163|      },
164|      (call) => taken.push({ call, by: "rule" }),
165|    );
166|    if (cuts.length === 0) return null;
167|    const bounds = [0, ...cuts, windows.length];
168|    const ranges = bounds.slice(1).map((end, i) => ({ startN: windows[bounds[i] ?? 0]?.startN ?? 0, endN: windows[end - 1]?.endN ?? 0 }));
169|    const result = await deps.meta.completeJson({
170|      system: "You split a book scene into ordered parts. Answer with JSON only, English titles in the style of the existing scene titles.",
171|      user:
172|        `Scene "${scene.title}" (${scene.id}, summary: ${scene.summary}) splits into ${ranges.length} parts. ` +
173|        `Give each part start_n, end_n, title, summary, and characters.\n` +
174|        ranges.map((r, i) => `PART ${i + 1} [${r.startN}..${r.endN}]:\n${paragraphs.filter((p) => p.n >= r.startN && p.n <= r.endN).map((p) => `[${p.n}] ${p.text}`).join("\n")}`).join("\n"),
175|      schemaName: "resplit_titles",
176|      schema: TITLES_SCHEMA,
177|    });
178|    trackMeta(usage, result);
179|    const parts = (result.data as { parts?: { start_n: number; end_n: number; title: string; summary: string; characters: unknown }[] }).parts ?? [];
180|    if (parts.length !== ranges.length || parts.some((p, i) => p.start_n !== ranges[i]?.startN || p.end_n !== ranges[i]?.endN)) {
181|      throw new Error(`scene ${scene.id} titles do not cover the split ranges`);
182|    }
183|    const ids = splitIds(scene.id, parts.length);
184|    const analyzed = await runPool(parts, 4, async (part, i) => {
185|      const text = paragraphs.filter((p) => p.n >= part.start_n && p.n <= part.end_n).map((p) => p.text).join("\n");
186|      const emotion = await classifyScene(
187|        { id: ids[i] ?? "", ch: scene.ch, start_n: part.start_n, end_n: part.end_n, title: part.title, summary: part.summary, characters: Array.isArray(part.characters) ? part.characters.map(String) : [] },
188|        text,
189|        book.title,
190|        chapterTitle.get(scene.ch) ?? "",
191|        deps,
192|        usage.meta,
193|      );
194|      usage.jevRequests += 1;
195|      if (emotion.jev) {
196|        usage.jevInputTokens += emotion.jev.input_tokens;
197|        usage.jevOutputTokens += emotion.jev.output_tokens;
198|      }
199|      return emotion;
200|    });
201|    const first = taken[0]?.call ?? bestBoundary(windows);
202|    const reason = taken.find((t) => t.reason)?.reason;
203|    return {
204|      scene,
205|      parts: parts.map((part, i) => ({
206|        scene: {
207|          id: ids[i] ?? "",
208|          ch: scene.ch,
209|          start_n: part.start_n,
210|          end_n: part.end_n,
211|          title: part.title,
212|          summary: part.summary,
213|          characters: Array.isArray(part.characters) ? part.characters.map(String) : [],
214|        } satisfies Scene,
215|        emotion: (analyzed[i] ?? { jev: null, muse_override: null, final: null, error: "missing part emotion" }) as SceneEmotion,
216|      })),
217|      entry: {
218|        from: scene.id,
219|        into: ids,
220|        at_n: ranges.map((r) => r.startN),
221|        margin: first?.margin ?? 0,
222|        left: first?.left ?? "calma",
223|        right: first?.right ?? "calma",
224|        decided_by: taken.some((t) => t.by === "muse") ? ("muse" as const) : ("rule" as const),
225|        ...(reason ? { reason } : {}),
226|      } satisfies ResplitEntry,
227|    };
228|  });
229|
230|  const byId = new Map(splitScenes.filter((s) => s !== null).map((s) => [s.scene.id, s]));
231|  const scenes: AnalyzedScene[] = [];
232|  const entries: ResplitEntry[] = [];
233|  for (const old of analysisFile.scenes) {
234|    const split = byId.get(old.id);
235|    if (!split) {
236|      scenes.push(old);
237|      continue;
238|    }
239|    entries.push(split.entry);
240|    for (const part of split.parts) scenes.push({ ...part.scene, ...part.emotion });
241|  }
242|  scenes.sort((a, b) => a.start_n - b.start_n);
243|  const problems = validateBookCoverage(book, scenes);
244|  if (problems.length > 0) throw new Error(`resplit breaks coverage: ${problems.map((p) => p.message).join("; ")}`);
245|
246|  const runningCost = jevCostUsd(usage.jevInputTokens) + metaCostUsd({ prompt: usage.meta.promptTokens, cached: usage.meta.cachedTokens, completion: usage.meta.completionTokens });
247|  if (runningCost > 0.5) throw new Error(`resplit cost $${runningCost.toFixed(2)} passed the $0.50 stop line`);
248|  usage.meta.costUsd = metaCostUsd({ prompt: usage.meta.promptTokens, cached: usage.meta.cachedTokens, completion: usage.meta.completionTokens });
249|  const jevCost = jevCostUsd(usage.jevInputTokens);
250|  const prevJev = analysisFile.provenance.jev;
251|  const prevMeta = analysisFile.provenance.meta;
252|  const segmentMeta = scenesFile.provenance.meta;
253|  writeFileSync(
254|    join(ctx.dir, "scenes.json"),
255|    `${JSON.stringify({
256|      bookId: book.id,
257|      textVersion: book.textVersion,
258|      scenes: scenes.map(({ id, ch, start_n, end_n, title, summary, characters }) => ({ id, ch, start_n, end_n, title, summary, characters })),
259|      provenance: {
260|        date: new Date().toISOString(),
261|        meta: {
262|          model: segmentMeta.model,
263|          requests: segmentMeta.requests + usage.meta.requests,
264|          prompt_tokens: segmentMeta.prompt_tokens + usage.meta.promptTokens,
265|          cached_tokens: segmentMeta.cached_tokens + usage.meta.cachedTokens,
266|          completion_tokens: segmentMeta.completion_tokens + usage.meta.completionTokens,
267|          cost_usd: segmentMeta.cost_usd + usage.meta.costUsd,
268|        },
269|      },
270|    })}\n`,
271|  );
272|  const totalJev = { model: deps.jev.model, requests: prevJev.requests + usage.jevRequests, input_tokens: prevJev.input_tokens + usage.jevInputTokens, output_tokens: prevJev.output_tokens + usage.jevOutputTokens, cost_usd: prevJev.cost_usd + jevCost };
273|  const totalMeta = {
274|    model: prevMeta.model,
275|    requests: prevMeta.requests + usage.meta.requests,
276|    prompt_tokens: prevMeta.prompt_tokens + usage.meta.promptTokens,
277|    cached_tokens: prevMeta.cached_tokens + usage.meta.cachedTokens,
278|    completion_tokens: prevMeta.completion_tokens + usage.meta.completionTokens,
279|    cost_usd: prevMeta.cost_usd + usage.meta.costUsd,
280|  };
281|  const overrides = scenes.filter((s) => s.muse_override !== null).length;
282|  writeFileSync(
283|    join(ctx.dir, "analysis.json"),
284|    `${JSON.stringify({
285|      bookId: book.id,
286|      textVersion: book.textVersion,
287|      scenes,
288|      override_rate: scenes.length > 0 ? overrides / scenes.length : 0,
289|      provenance: {
290|        date: new Date().toISOString(),
291|        jev: totalJev,
292|        meta: totalMeta,
293|        total_cost_usd: totalJev.cost_usd + totalMeta.cost_usd,
294|        resplit: {
295|          auto_margin: RESPLIT_AUTO_MARGIN,
296|          ask_margin: RESPLIT_ASK_MARGIN,
297|          candidates: candidates.length,
298|          windows_classified: windowsClassified,
299|          splits: entries,
300|          jev: { model: deps.jev.model, requests: usage.jevRequests, input_tokens: usage.jevInputTokens, output_tokens: usage.jevOutputTokens, cost_usd: jevCost },
301|          meta: { model: usage.meta.model, requests: usage.meta.requests, prompt_tokens: usage.meta.promptTokens, cached_tokens: usage.meta.cachedTokens, completion_tokens: usage.meta.completionTokens, cost_usd: usage.meta.costUsd },
302|        },
303|      },
304|    })}\n`,
305|  );
306|  return scenes;
307|}

