Read text file `core/resplit.ts`.
1|// Resplit rule: split a scene only where the dominant emotion changes
2|// strongly and stays changed along the text. Pure, no network.
3|import { EMOTIONS } from "./types";
4|import type { EmotionId, Vector8 } from "./types";
5|import { countWords } from "./reader";
6|
7|export const RESPLIT_AUTO_MARGIN = 0.3;
8|export const RESPLIT_ASK_MARGIN = 0.15;
9|export const RESPLIT_MIN_PART_WORDS = 120;
10|export const RESPLIT_MIN_SCENE_WORDS = 240;
11|export const RESPLIT_CANDIDATE_WORDS = 350;
12|export const RESPLIT_LOW_TOP = 0.5;
13|export const RESPLIT_LOW_GAP = 0.15;
14|export const RESPLIT_WINDOW_MIN = 100;
15|export const RESPLIT_WINDOW_MAX = 160;
16|
17|export interface ResplitParagraph {
18|  n: number;
19|  text: string;
20|}
21|
22|export interface ResplitWindow {
23|  startN: number;
24|  endN: number;
25|  words: number;
26|  vector: Vector8;
27|}
28|
29|export type WindowSpan = Pick<ResplitWindow, "startN" | "endN" | "words">;
30|
31|export interface SplitCall {
32|  index: number;
33|  margin: number;
34|  left: EmotionId;
35|  right: EmotionId;
36|}
37|
38|export function topOf(vector: Vector8): { id: EmotionId; value: number; gap: number } {
39|  let id: EmotionId = EMOTIONS[0];
40|  let value = -Infinity;
41|  let second = -Infinity;
42|  for (const key of EMOTIONS) {
43|    const v = vector[key];
44|    if (v > value) {
45|      second = value;
46|      id = key;
47|      value = v;
48|    } else if (v > second) {
49|      second = v;
50|    }
51|  }
52|  return { id, value, gap: value - second };
53|}
54|
55|export function isResplitCandidate(words: number, final: { vector: Vector8 } | null): boolean {
56|  if (final === null || words < RESPLIT_MIN_SCENE_WORDS) return false;
57|  if (words > RESPLIT_CANDIDATE_WORDS) return true;
58|  const { value, gap } = topOf(final.vector);
59|  return value < RESPLIT_LOW_TOP || gap < RESPLIT_LOW_GAP;
60|}
61|
62|// Consecutive windows of whole paragraphs, greedily about 100 to 160
63|// words each. A single long paragraph is its own window.
64|export function buildWindows(paragraphs: ResplitParagraph[]): WindowSpan[] {
65|  const windows: WindowSpan[] = [];
66|  let startN = 0;
67|  let endN = 0;
68|  let words = 0;
69|  const flush = () => {
70|    if (words === 0 && endN === 0) return;
71|    windows.push({ startN, endN, words });
72|    startN = 0;
73|    endN = 0;
74|    words = 0;
75|  };
76|  for (const p of paragraphs) {
77|    if (words >= RESPLIT_WINDOW_MIN) flush();
78|    if (words === 0) startN = p.n;
79|    endN = p.n;
80|    words += countWords(p.text);
81|  }
82|  flush();
83|  const last = windows[windows.length - 1];
84|  const prev = windows[windows.length - 2];
85|  if (last && prev && last.words < RESPLIT_WINDOW_MIN) {
86|    prev.endN = last.endN;
87|    prev.words += last.words;
88|    windows.pop();
89|  }
90|  return windows;
91|}
92|
93|export function meanVector(windows: Pick<ResplitWindow, "words" | "vector">[]): Vector8 {
94|  const total = windows.reduce((sum, w) => sum + w.words, 0);
95|  const mean = {} as Vector8;
96|  for (const id of EMOTIONS) {
97|    mean[id] = 0;
98|    for (const w of windows) mean[id] += w.vector[id] * (total > 0 ? w.words / total : 1 / windows.length);
99|  }
100|  return mean;
101|}
102|
103|// A side holds when it reaches 120 words and the mood persists past
104|// one short window: two windows, or one window of 120 words itself.
105|function holds(windows: Pick<ResplitWindow, "words">[]): boolean {
106|  const words = windows.reduce((sum, w) => sum + w.words, 0);
107|  if (words < RESPLIT_MIN_PART_WORDS) return false;
108|  return windows.length >= 2 || (windows[0]?.words ?? 0) >= RESPLIT_MIN_PART_WORDS;
109|}
110|
111|export function bestBoundary(windows: ResplitWindow[]): SplitCall | null {
112|  let best: SplitCall | null = null;
113|  for (let index = 1; index < windows.length; index++) {
114|    const leftWindows = windows.slice(0, index);
115|    const rightWindows = windows.slice(index);
116|    if (!holds(leftWindows) || !holds(rightWindows)) continue;
117|    const left = meanVector(leftWindows);
118|    const right = meanVector(rightWindows);
119|    const a = topOf(left).id;
120|    const b = topOf(right).id;
121|    if (a === b) continue;
122|    const margin = Math.min(left[a] - left[b], right[b] - right[a]);
123|    if (best === null || margin > best.margin) best = { index, margin, left: a, right: b };
124|  }
125|  return best;
126|}
127|
128|export function decideMargin(margin: number): "auto" | "ask" | "none" {
129|  if (margin >= RESPLIT_AUTO_MARGIN) return "auto";
130|  if (margin >= RESPLIT_ASK_MARGIN) return "ask";
131|  return "none";
132|}
133|
134|// Binary segmentation: split at the strongest boundary, then recurse
135|// on each side. The asker resolves ambiguous margins; record keeps
136|// each taken boundary for provenance.
137|export async function planSplits(
138|  windows: ResplitWindow[],
139|  askSplit: (call: SplitCall) => Promise<boolean>,
140|  record?: (call: SplitCall, decidedBy: "rule" | "muse") => void,
141|): Promise<number[]> {
142|  const best = bestBoundary(windows);
143|  if (best === null || decideMargin(best.margin) === "none") return [];
144|  const kind = decideMargin(best.margin);
145|  if (kind === "ask" && !(await askSplit(best))) return [];
146|  record?.(best, kind === "ask" ? "muse" : "rule");
147|  const left = await planSplits(windows.slice(0, best.index), askSplit, record);
148|  const right = (await planSplits(windows.slice(best.index), askSplit, record)).map((i) => i + best.index);
149|  return [...left, best.index, ...right];
150|}
151|
152|// First part keeps the scene id; later parts add a letter suffix.
153|export function splitIds(baseId: string, count: number): string[] {
154|  return Array.from({ length: count }, (_, i) => (i === 0 ? baseId : `${baseId}${String.fromCharCode(97 + i)}`));
155|}

